def bootstrap_room_participants(apps, schema_editor):
    Room = apps.get_model("main", "Room")
    RoomParticipant = apps.get_model("main", "RoomParticipant")

    for room in Room.objects.all().iterator():
        if room.code:
            normalized_code = room.code.upper()
            if normalized_code != room.code:
                room.code = normalized_code
                room.save(update_fields=["code"])
        RoomParticipant.objects.get_or_create(
            room_id=room.id,
            user_id=room.creator_id,
            defaults={"role": "owner"},
        )


